function canonicalizeLabel(label) {
  if (typeof label !== 'string') throw new TypeError('label must be a string');
  const key = label
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');
  if (key.length === 0) throw new TypeError('label has no usable characters');
  return key;
}

function buildLabelIndex(labels) {
  if (!Array.isArray(labels)) throw new TypeError('labels must be an array');
  const result = Object.create(null);
  for (const label of labels) {
    const key = canonicalizeLabel(label);
    result[key] = label;
  }
  return result;
}

module.exports = { canonicalizeLabel, buildLabelIndex };

