'use strict';
const assert = require('node:assert');
const api = require('./solution');

assert.strictEqual(Reflect.ownKeys(api).length, 2);
assert.strictEqual(typeof api.canonicalizeLabel, 'function');
assert.strictEqual(typeof api.buildLabelIndex, 'function');
const { canonicalizeLabel, buildLabelIndex } = api;
const typeError = (fn) => assert.throws(fn, TypeError);

assert.strictEqual(canonicalizeLabel('  Hello---WORLD 42!! '), 'hello_world_42');
assert.strictEqual(canonicalizeLabel('Already_valid'), 'already_valid');
assert.strictEqual(canonicalizeLabel('A...B___C'), 'a_b_c');
assert.strictEqual(canonicalizeLabel('Crème brûlée'), 'cr_me_br_l_e');
assert.strictEqual(canonicalizeLabel('  123  '), '123');
assert.strictEqual(canonicalizeLabel('x+y/z'), 'x_y_z');

for (const invalid of ['', '   ', '---___!!!', 12, null, undefined, new String('x')]) {
  typeError(() => canonicalizeLabel(invalid));
}

const labels = [' First Label ', 'SECOND.label', 'Third'];
const before = labels.slice();
const index = buildLabelIndex(labels);
assert.strictEqual(Object.getPrototypeOf(index), null);
assert.deepStrictEqual(Object.keys(index), ['first_label', 'second_label', 'third']);
assert.strictEqual(index.first_label, ' First Label ');
assert.strictEqual(index.second_label, 'SECOND.label');
assert.strictEqual(index.third, 'Third');
assert.deepStrictEqual(labels, before);
labels[0] = 'changed later';
assert.strictEqual(index.first_label, ' First Label ');

const empty = buildLabelIndex([]);
assert.strictEqual(Object.getPrototypeOf(empty), null);
assert.deepStrictEqual(Object.keys(empty), []);

const special = buildLabelIndex(['constructor', '__proto__']);
assert.strictEqual(Object.getPrototypeOf(special), null);
assert.strictEqual(special.constructor, 'constructor');
assert.strictEqual(special.proto, '__proto__');

typeError(() => buildLabelIndex('not an array'));
typeError(() => buildLabelIndex([1]));
typeError(() => buildLabelIndex(['valid', '---']));
typeError(() => buildLabelIndex(['A B', 'a--b']));
typeError(() => buildLabelIndex(['same', 'same']));
const sparse = new Array(2);
sparse[1] = 'present';
typeError(() => buildLabelIndex(sparse));

